CREATE VIEW IF NOT EXISTS vw_company_financial_coverage AS SELECT c.id company_id,c.symbol,p.frequency,p.period_end,m.statement,count(DISTINCT f.metric_id) metric_count FROM ft_financials f JOIN dm_company c ON c.id=f.company_id JOIN dm_period p ON p.id=f.period_id JOIN dm_metric m ON m.id=f.metric_id WHERE EXISTS(SELECT 1 FROM ft_source_reference r JOIN dm_snapshot s ON s.id=r.snapshot_id WHERE r.fact_id=f.id AND s.status='COMPLETE') GROUP BY c.id,c.symbol,p.frequency,p.period_end,m.statement;
CREATE VIEW IF NOT EXISTS vw_company_financial_growth AS SELECT a.company_id,a.symbol,a.frequency,a.period_end,CASE WHEN b.revenue>0 THEN 100.0*(a.revenue/b.revenue-1) END revenue_yoy_pct,CASE WHEN b.net_income>0 THEN 100.0*(a.net_income/b.net_income-1) END earnings_yoy_pct,CASE WHEN b.ocf>0 THEN 100.0*(a.ocf/b.ocf-1) END ocf_yoy_pct FROM vw_company_financial_base a LEFT JOIN vw_company_financial_base b ON a.company_id=b.company_id AND a.frequency=b.frequency AND b.period_end=date(a.period_end,'-1 year');
CREATE VIEW IF NOT EXISTS vw_company_profitability AS SELECT a.company_id,a.symbol,a.frequency,a.period_end,CASE WHEN a.revenue>0 THEN 100.0*a.net_income/a.revenue END net_margin_pct,CASE WHEN a.revenue>0 THEN 100.0*a.gross_profit/a.revenue END gross_margin_pct,CASE WHEN a.revenue>0 THEN 100.0*a.ebitda/a.revenue END ebitda_margin_pct,CASE WHEN a.frequency='ANNUAL' AND a.equity>0 AND b.equity>0 THEN 200.0*a.net_income/(a.equity+b.equity) END roe_pct,CASE WHEN a.frequency='ANNUAL' AND a.assets>0 AND b.assets>0 THEN 200.0*a.net_income/(a.assets+b.assets) END roa_pct FROM vw_company_financial_base a LEFT JOIN vw_company_financial_base b ON a.company_id=b.company_id AND a.frequency=b.frequency AND b.period_end=date(a.period_end,'-1 year');
CREATE VIEW IF NOT EXISTS vw_company_financial_strength AS SELECT a.company_id,a.symbol,a.frequency,a.period_end,CASE WHEN a.equity>0 THEN a.debt/a.equity END debt_equity,CASE WHEN a.assets>0 THEN a.debt/a.assets END debt_assets,CASE WHEN c.industry IS NOT NULL AND c.industry NOT LIKE '%Financial%' AND c.industry NOT LIKE '%Insurance%' AND c.industry NOT LIKE '%Bank%' AND a.current_liabilities>0 THEN a.current_assets/a.current_liabilities END current_ratio,a.debt-a.cash net_debt_cr FROM vw_company_financial_base a JOIN dm_company c ON c.id=a.company_id;
CREATE VIEW IF NOT EXISTS vw_company_cashflow_quality AS SELECT company_id,symbol,frequency,period_end,CASE WHEN net_income>0 THEN ocf/net_income END ocf_to_income,CASE WHEN net_income>0 THEN fcf/net_income END fcf_to_income,CASE WHEN revenue>0 THEN 100.0*fcf/revenue END fcf_margin_pct FROM vw_company_financial_base;
CREATE VIEW IF NOT EXISTS vw_index_overlap AS WITH m AS (SELECT DISTINCT index_id,company_id FROM vw_index_constituents),n AS (SELECT index_id,count(*) total FROM m GROUP BY index_id),p AS (SELECT a.index_id index_a,b.index_id index_b,count(*) common_count FROM m a JOIN m b ON a.company_id=b.company_id AND a.index_id<b.index_id GROUP BY a.index_id,b.index_id) SELECT p.*,1.0*common_count/(a.total+b.total-common_count) jaccard FROM p JOIN n a ON a.index_id=p.index_a JOIN n b ON b.index_id=p.index_b;
